function [z, s] = stream_normal(s)
%STREAM_NORMAL  a normal draw by Box-Muller (the spare kept), and the stream advanced.
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    persistent K1 K2 BH BL U r
    if s(6) ~= 0
        z = s(5); s(5) = 0; s(6) = 0;
        return;
    end
    % its two uniform draws read from kept blocks of stream_block, as stream_uniform reads them
    if isempty(r), K1 = NaN(64, 1); K2 = K1; BH = K1; BL = K1; U = zeros(64, 257); r = 1; end
    nl = s(4) + 1; nh = s(3);
    if nl == 4294967296, nl = 0; nh = mod(nh + 1, 4294967296); end
    if ~(K1(r) == s(1) && K2(r) == s(2))
        r = find(K1 == s(1) & K2 == s(2), 1);
        if isempty(r)
            r = find(isnan(K1), 1); if isempty(r), r = 1 + mod(nl, 64); end
            K1(r) = s(1); K2(r) = s(2); BH(r) = NaN;
        end
    end
    j = nl - BL(r);
    if ~(BH(r) == nh && j >= 1 && j <= 256)
        BH(r) = nh; BL(r) = nl - 1; U(r, :) = asils.pc.stream_block(s(1), s(2), nh, nl - 1).'; j = 1;
    end
    u1 = U(r, j); u2 = U(r, j + 1);
    if nl == 4294967295, s(3) = mod(nh + 1, 4294967296); s(4) = 0; else, s(3) = nh; s(4) = nl + 1; end
    rr = sqrt(-2*log(u1));
    s(5) = rr*sin(2*pi*u2); s(6) = 1;
    z = rr*cos(2*pi*u2);
end
